PRAGMA foreign_keys=ON;
CREATE TABLE metadata(key TEXT PRIMARY KEY,value_json TEXT NOT NULL);
CREATE TABLE sources(id TEXT PRIMARY KEY,title TEXT NOT NULL,url TEXT NOT NULL,checked_on TEXT NOT NULL,kind TEXT NOT NULL);
CREATE TABLE families(id TEXT PRIMARY KEY,title_ru TEXT NOT NULL,details_json TEXT NOT NULL);
CREATE TABLE resources(id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL,description_ru TEXT NOT NULL,cost_model_ru TEXT,license_label TEXT,license_note_ru TEXT,video_reuse_route_ru TEXT,checked_on TEXT, runtime_tested INTEGER NOT NULL DEFAULT 0,details_json TEXT NOT NULL);
CREATE TABLE patterns(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id),name_en TEXT NOT NULL,name_ru TEXT NOT NULL,description_ru TEXT NOT NULL,status TEXT NOT NULL,loop_mode TEXT,details_json TEXT NOT NULL);
CREATE TABLE pattern_tags(pattern_id TEXT NOT NULL REFERENCES patterns(id),kind TEXT NOT NULL,tag TEXT NOT NULL,PRIMARY KEY(pattern_id,kind,tag));
CREATE TABLE candidate_resources(pattern_id TEXT NOT NULL REFERENCES patterns(id),resource_id TEXT NOT NULL REFERENCES resources(id),status TEXT NOT NULL,PRIMARY KEY(pattern_id,resource_id));
CREATE TABLE resource_sources(resource_id TEXT NOT NULL REFERENCES resources(id),source_id TEXT NOT NULL REFERENCES sources(id),PRIMARY KEY(resource_id,source_id));
CREATE TABLE pattern_sources(pattern_id TEXT NOT NULL REFERENCES patterns(id),source_id TEXT NOT NULL REFERENCES sources(id),PRIMARY KEY(pattern_id,source_id));
CREATE TABLE preset_specifications(id TEXT PRIMARY KEY,pattern_id TEXT NOT NULL REFERENCES patterns(id),status TEXT NOT NULL,specification_json TEXT NOT NULL);
CREATE TABLE implementations(id TEXT PRIMARY KEY,pattern_id TEXT NOT NULL REFERENCES patterns(id),resource_id TEXT REFERENCES resources(id),code_path TEXT,package_version TEXT,time_driver TEXT,deterministic INTEGER,seekable INTEGER,status TEXT NOT NULL,license_url TEXT,tested_on TEXT,details_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE assets(id TEXT PRIMARY KEY,pattern_id TEXT REFERENCES patterns(id),implementation_id TEXT REFERENCES implementations(id),role TEXT NOT NULL,source_url TEXT,local_path TEXT,sha256 TEXT,format TEXT,has_alpha INTEGER,license_url TEXT,license_checked_on TEXT,details_json TEXT NOT NULL DEFAULT '{}');
CREATE INDEX idx_patterns_family ON patterns(family_id);
CREATE INDEX idx_tags_lookup ON pattern_tags(kind,tag);
CREATE INDEX idx_resource_kind ON resources(kind);
CREATE INDEX idx_candidates_resource ON candidate_resources(resource_id);
CREATE TABLE animation_classes(id TEXT PRIMARY KEY,type_id TEXT NOT NULL REFERENCES families(id),name_ru TEXT NOT NULL,description_ru TEXT NOT NULL,details_json TEXT NOT NULL);
CREATE TABLE animation_examples(id TEXT PRIMARY KEY,provider TEXT NOT NULL REFERENCES resources(id),name TEXT NOT NULL,type_id TEXT NOT NULL REFERENCES families(id),class_id TEXT NOT NULL REFERENCES animation_classes(id),pattern_id TEXT NOT NULL REFERENCES patterns(id),demo_url TEXT NOT NULL,preview_kind TEXT NOT NULL,source_status TEXT,details_json TEXT NOT NULL);
CREATE TABLE example_tags(example_id TEXT NOT NULL REFERENCES animation_examples(id),kind TEXT NOT NULL,tag TEXT NOT NULL,PRIMARY KEY(example_id,kind,tag));
CREATE TABLE example_files(example_id TEXT NOT NULL REFERENCES animation_examples(id),role TEXT NOT NULL,path TEXT NOT NULL,PRIMARY KEY(example_id,role,path));
CREATE INDEX idx_example_type ON animation_examples(type_id,class_id);
CREATE INDEX idx_example_provider ON animation_examples(provider);
CREATE INDEX idx_example_tags ON example_tags(kind,tag);
CREATE TABLE example_assets(example_id TEXT NOT NULL REFERENCES animation_examples(id),asset_id TEXT NOT NULL REFERENCES assets(id),PRIMARY KEY(example_id,asset_id));
